     1|/**
     2| * IVX Twilio SMS sender — fallback/alternative to AWS SNS for owner notifications.
     3| *
     4| * Uses the Twilio Messaging API (https://messaging.twilio.com/v1) to send a
     5| * single SMS from the configured messaging service or from-number. Designed as
     6| * a drop-in alternative for sendSnsSms in ivx-autonomous-sms-notifier.ts.
     7| *
     8| * Credentials:
     9| *   - IVX_TWILIO_ACCOUNT_SID
    10| *   - IVX_TWILIO_AUTH_TOKEN
    11| *   - IVX_TWILIO_MESSAGING_SERVICE_SID (preferred — uses the ivxholding.com service)
    12| *   - IVX_TWILIO_FROM_PHONE (fallback if no messaging service configured)
    13| *
    14| * Marker: ivx-twilio-sms-2026-08-11
    15| */
    16|
    17|import { normalizePhoneToE164 } from './ivx-sns-sms';
    18|
    19|export type TwilioSmsResult = {
    20|  ok: boolean;
    21|  status: 'sent' | 'missing_config' | 'rate_limited' | 'failed';
    22|  messageId?: string;
    23|  httpStatus?: number;
    24|  to?: string;
    25|  from?: string;
    26|  missingEnvNames: string[];
    27|  error?: string;
    28|  sentAt: string;
    29|};
    30|
    31|function readEnv(name: string): string {
    32|  const v = process.env[name];
    33|  return typeof v === 'string' ? v.trim() : '';
    34|}
    35|
    36|/** True when Twilio has enough config to attempt a send. */
    37|export function isTwilioSmsConfigured(): boolean {
    38|  return Boolean(readEnv('IVX_TWILIO_ACCOUNT_SID') && readEnv('IVX_TWILIO_AUTH_TOKEN'));
    39|}
    40|
    41|function resolveFrom(): { messagingServiceSid?: string; fromPhone?: string } {
    42|  const messagingServiceSid = readEnv('IVX_TWILIO_MESSAGING_SERVICE_SID');
    43|  const fromPhone = normalizePhoneToE164(readEnv('IVX_TWILIO_FROM_PHONE'));
    44|  return messagingServiceSid ? { messagingServiceSid } : { fromPhone };
    45|}
    46|
    47|/**
    48| * Send a single SMS via Twilio Messaging API.
    49| * Returns structured status; never throws.
    50| */
    51|export async function sendTwilioSms(input: {
    52|  to: string;
    53|  message: string;
    54|}): Promise<TwilioSmsResult> {
    55|  const sentAt = new Date().toISOString();
    56|  const accountSid = readEnv('IVX_TWILIO_ACCOUNT_SID');
    57|  const authToken = readEnv('IVX_TWILIO_AUTH_TOKEN');
    58|  const to = normalizePhoneToE164(input.to);
    59|  const from = resolveFrom();
    60|
    61|  const missingEnvNames: string[] = [];
    62|  if (!accountSid) missingEnvNames.push('IVX_TWILIO_ACCOUNT_SID');
    63|  if (!authToken) missingEnvNames.push('IVX_TWILIO_AUTH_TOKEN');
    64|  if (!from.messagingServiceSid && !from.fromPhone) missingEnvNames.push('IVX_TWILIO_MESSAGING_SERVICE_SID or IVX_TWILIO_FROM_PHONE');
    65|  if (!to) missingEnvNames.push('destination phone');
    66|
    67|  if (missingEnvNames.length > 0) {
    68|    return {
    69|      ok: false,
    70|      status: 'missing_config',
    71|      to: to || undefined,
    72|      missingEnvNames,
    73|      error: 'Twilio SMS is not fully configured.',
    74|      sentAt,
    75|    };
    76|  }
    77|
    78|  if (!/^\+\d{8,15}$/.test(to)) {
    79|    return {
    80|      ok: false,
    81|      status: 'failed',
    82|      to,
    83|      missingEnvNames,
    84|      error: 'Destination phone is not a valid E.164 number.',
    85|      sentAt,
    86|    };
    87|  }
    88|
    89|  const body = new URLSearchParams();
    90|  body.set('To', to);
    91|  body.set('Body', input.message.slice(0, 1600));
    92|  if (from.messagingServiceSid) {
    93|    body.set('MessagingServiceSid', from.messagingServiceSid);
    94|  } else if (from.fromPhone) {
    95|    body.set('From', from.fromPhone);
    96|  }
    97|
    98|  const credentials = Buffer.from(`${accountSid}:${authToken}`).toString('base64');
    99|  const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
   100|
   101|  try {
   102|    const response = await fetch(url, {
   103|      method: 'POST',
   104|      headers: {
   105|        Authorization: `Basic ${credentials}`,
   106|        'Content-Type': 'application/x-www-form-urlencoded',
   107|      },
   108|      body: body.toString(),
   109|    });
   110|
   111|    const text = await response.text();
   112|    const json = response.ok ? (JSON.parse(text) as Record<string, unknown>) : null;
   113|
   114|    if (!response.ok) {
   115|      const parsed = (() => {
   116|        try { return JSON.parse(text) as { message?: string; code?: number | string }; }
   117|        catch { return null; }
   118|      })();
   119|      const errorMessage = parsed?.message ?? text.slice(0, 300) ?? `Twilio responded ${response.status}`;
   120|      const isRateLimit = response.status === 429 || /rate.*limit|too many/i.test(errorMessage);
   121|      return {
   122|        ok: false,
   123|        status: isRateLimit ? 'rate_limited' : 'failed',
   124|        to,
   125|        from: from.messagingServiceSid || from.fromPhone,
   126|        httpStatus: response.status,
   127|        missingEnvNames,
   128|        error: errorMessage,
   129|        sentAt,
   130|      };
   131|    }
   132|
   133|    return {
   134|      ok: true,
   135|      status: 'sent',
   136|      to,
   137|      from: from.messagingServiceSid || from.fromPhone,
   138|      messageId: typeof json?.sid === 'string' ? json.sid : undefined,
   139|      httpStatus: response.status,
   140|      missingEnvNames,
   141|      sentAt,
   142|    };
   143|  } catch (error) {
   144|    return {
   145|      ok: false,
   146|      status: 'failed',
   147|      to,
   148|      from: from.messagingServiceSid || from.fromPhone,
   149|      missingEnvNames,
   150|      error: error instanceof Error ? error.message : 'Twilio SMS send request failed.',
   151|      sentAt,
   152|    };
   153|  }
   154|}

